// Normalization, Field Selection, Fallbacks, and Dynamic Tag Interpolation
const body = $('Start Campaign Webhook').first().json.body;
const items = $input.all();
const sendLimit = Number(body.sendLimit) || 100;
const usePersonal = body.primaryRecipientField === 'personal_email';

const outputList = [];
const seenEmails = new Set();
let validCount = 0;

for (const item of items) {
  const row = item.json;

  // Extract and clean recipient email
  let targetEmail = usePersonal && row['Personal Email'] ? String(row['Personal Email']) : String(row['Email'] || row['email'] || row['Email Address'] || row['email_address'] || '');
  targetEmail = targetEmail.trim().toLowerCase();

  if (!targetEmail || !targetEmail.includes('@')) {
    continue;
  }

  const isDuplicate = seenEmails.has(targetEmail);
  if (!isDuplicate) {
    seenEmails.add(targetEmail);
    validCount++;
  }

  // Extract field values from Google Sheet
  const rawFirstName = String(row['First Name'] || row['firstName'] || row['Name'] || row['first_name'] || '').trim();
  const rawLastName = String(row['Last Name'] || row['lastName'] || row['last_name'] || '').trim();
  const rawWebsite = String(row['Website'] || row['website'] || row['Site'] || row['site'] || row['url'] || '').trim();
  const rawAddress = String(row['Address'] || row['address'] || row['Company'] || row['company'] || row['Location'] || '').trim();
  const rawContact = String(row['Contact'] || row['contact'] || row['Phone'] || row['phone'] || '').trim();

  // Intelligent Fallbacks if Sheet column is empty or missing:
  const firstName = rawFirstName || 'there';
  const lastName = rawLastName || '';
  const website = rawWebsite || 'your website';
  const address = rawAddress || 'your company';
  const company = rawAddress || 'your team';
  const contact = rawContact || '';

  // Helper to replace all merge tags with fallback protection
  const interpolate = (templateText) => {
    if (!templateText) return '';
    return String(templateText)
      .replace(/\{\{\s*(firstName|firstname|first_name|fname|name)\s*\}\}/gi, firstName)
      .replace(/\{\{\s*(lastName|lastname|last_name|lname)\s*\}\}/gi, lastName)
      .replace(/\{\{\s*(email|mail)\s*\}\}/gi, targetEmail)
      .replace(/\{\{\s*(website|site|url)\s*\}\}/gi, website)
      .replace(/\{\{\s*(address|location)\s*\}\}/gi, address)
      .replace(/\{\{\s*(company|companyname)\s*\}\}/gi, company)
      .replace(/\{\{\s*(contact|phone|phonenumber|mobile)\s*\}\}/gi, contact);
  };

  const finalSubject = interpolate(body.subject || 'Quick question about {{website}}');
  const finalHtmlBody = interpolate(body.htmlBody || '<p>Hi {{firstName}},</p><p>I was checking {{website}} and noticed key growth opportunities.</p>');
  const finalTextBody = interpolate(body.textBody || 'Hi {{firstName}},\n\nI was checking {{website}} and noticed key growth opportunities.');

  outputList.push({
    json: {
      campaignId: body.campaignId,
      recipientEmail: targetEmail,
      firstName: firstName,
      lastName: lastName,
      address: address,
      contact: contact,
      website: website,
      subject: finalSubject,
      fromName: body.fromName,
      fromEmail: body.fromEmail,
      htmlBody: finalHtmlBody,
      textBody: finalTextBody,
      isDuplicate: isDuplicate
    }
  });

  if (validCount >= sendLimit && !isDuplicate) break;
}

return outputList;
